Java.perform(function() {
    console.log("[*] Hooking WebViewClient URL loading handlers...");

    var WebView = Java.use("android.webkit.WebView");
    var WebViewClient = Java.use("android.webkit.WebViewClient");
    var Uri = Java.use("android.net.Uri");

    // Per-thread bookkeeping so we can tell which URL-inspection calls happen
    // *while* one of the app's URL handlers is executing (handlers may run on
    // several threads concurrently).
    var handlerActive = {};   // threadId -> bool
    var inspectionLog = {};   // threadId -> array of method names

    function tid() { return Process.getCurrentThreadId(); }

    // A real allowlist/validation check reads the URL's host/scheme/path. We hook
    // those accessors and record any call made from inside a handler. If a handler
    // never calls them, it makes no host-based validation decision.
    ["getHost", "getScheme", "getPath"].forEach(function(name) {
        Uri[name].implementation = function() {
            var t = tid();
            if (handlerActive[t]) {
                inspectionLog[t].push(name);
            }
            return this[name]();
        };
    });

    function reportInspection(t) {
        var calls = inspectionLog[t] || [];
        if (calls.length === 0) {
            console.log("    URL inspection during handler: NONE (no host/scheme/path check -> no validation)");
        } else {
            console.log("    URL inspection during handler: " + calls.join(", "));
        }
    }

    // Reveal the WebViewClient the app registers and which handlers it overrides.
    WebView.setWebViewClient.implementation = function(client) {
        this.setWebViewClient(client);
        var cls = client.getClass();
        console.log("\n[*] setWebViewClient called");
        console.log("    WebViewClient implementation: " + cls.getName());
        var methods = cls.getDeclaredMethods();
        for (var i = 0; i < methods.length; i++) {
            var n = methods[i].getName();
            if (n === "shouldOverrideUrlLoading" || n === "shouldInterceptRequest") {
                console.log("    [!] Overrides " + n + " (custom URL handling)");
            }
        }
    };

    WebViewClient.shouldOverrideUrlLoading.overload('android.webkit.WebView', 'android.webkit.WebResourceRequest').implementation = function(view, request) {
        var t = tid();
        var url = request.getUrl().toString();
        handlerActive[t] = true;
        inspectionLog[t] = [];
        var result = this.shouldOverrideUrlLoading(view, request);
        handlerActive[t] = false;
        console.log("\n[shouldOverrideUrlLoading] URL: " + url);
        reportInspection(t);
        console.log("    -> returned " + result + " (false = URL loaded without validation)");
        return result;
    };

    WebViewClient.shouldInterceptRequest.overload('android.webkit.WebView', 'android.webkit.WebResourceRequest').implementation = function(view, request) {
        var t = tid();
        var url = request.getUrl().toString();
        handlerActive[t] = true;
        inspectionLog[t] = [];
        var result = this.shouldInterceptRequest(view, request);
        handlerActive[t] = false;
        console.log("\n[shouldInterceptRequest] URL: " + url);
        reportInspection(t);
        console.log("    -> " + (result != null ? "custom response returned" : "default loading (no validation)"));
        return result;
    };

    console.log("[*] WebViewClient hooks installed successfully");
});

if (Java.available) {
    Java.perform(function() {

        // --- Configuration Constants ---
        const CRYPTO_OP_ENCRYPT_DECRYPT = "encryption/decryption";
        const CRYPTO_OP_SIGN_VERIFY = "sign/verify";

        // Storage for tracking key usage: { key_toString: usage_type }
        const usedKeys = {};

        // --- Core Reflection Setup Function ---
        /**
         * Initializes and returns the reflected Method object for Object.toString().
         */
        function getToStringMethodRef() {
            try {
                const Object = Java.use('java.lang.Object');
                const toStringMethod = Object.class.getDeclaredMethod("toString", []);
                toStringMethod.setAccessible(true);
                return toStringMethod;
            } catch (e) {
                console.log("❌ CRITICAL SETUP ERROR: Failed to prepare toString reflection: " + e);
                return null;
            }
        }

        // Execute the reflection setup once at the start
        const toStringMethodRef = getToStringMethodRef();

        if (!toStringMethodRef) {
            console.log("❌ Script halted: Reflection setup failed.");
            return;
        }

        try {
            // --- Java Class References ---
            const Cipher = Java.use("javax.crypto.Cipher");
            const Signature = Java.use("java.security.Signature");

            // --- Helper Functions ---

            /**
             * Safely invokes the Java toString() method on the key/certificate and logs usage.
             */
            function logKeyDetails(key, certificate, cryptoOp) {

                // If a certificate is provided, use its PublicKey for tracking
                let trackingKey = key;
                if (certificate) {
                    try {
                        trackingKey = certificate.getPublicKey();
                        console.log("  Tracking Key: Certificate's Public Key");
                    } catch (e) {
                        console.log(`  ERROR: Failed to get Public Key from Certificate: ${e}`);
                        return;
                    }
                }

                if (trackingKey === null) {
                    console.log("  ERROR: Key object is null, skipping tracking.");
                    return;
                }

                let javaToStringResult = "UNKNOWN_KEY_ID";

                try {
                    // Invoke toString() using the pre-calculated reference.
                    // Pass the instance (trackingKey) and an empty array of arguments ([]).
                    javaToStringResult = toStringMethodRef.invoke(trackingKey, []);
                } catch (e) {
                    // Fallback to native pointer if reflection fails
                    try {
                        javaToStringResult = trackingKey.toPointer().toString();
                    } catch (pe) {
                        javaToStringResult = `ERROR_ID_${Date.now()}`;
                    }
                    console.log(`  WARNING: Reflection failed. Tracking ID: ${javaToStringResult}`);
                }

                console.log(`  ${cryptoOp} with key: "${javaToStringResult}"`);

                // --- Usage Tracking Logic ---
                const storedOp = usedKeys[javaToStringResult];

                if (storedOp !== undefined && storedOp !== cryptoOp) {
                    console.log("!!! WARNING: This key is used for multiple, conflicting purposes: " + storedOp + " and " + cryptoOp);
                } else if (storedOp === undefined) {
                    // Store the key's first detected usage
                    usedKeys[javaToStringResult] = cryptoOp;
                }
            }

            /**
             * Logs the current Java stack trace.
             */
            function logStackTrace() {
                console.log("  Stack Trace:");
                const exception = Java.use("java.lang.Exception").$new();
                const stackTraceElements = exception.getStackTrace();
                for (let i = 0; i < stackTraceElements.length; i++) {
                    const element = stackTraceElements[i];
                    if (i < 10) { // Limit stack depth for cleaner output
                        console.log("    " + element.toString());
                    }
                }
                console.log("  --- End Stack Trace ---");
            }


            // --- HOOKS: Cipher (Encryption/Decryption) ---

            Cipher.init.overload('int', 'java.security.Key').implementation = function(opmode, key) {
                console.log("\n🔒 *** Cipher.init(Key) HOOKED ***");
                logKeyDetails(key, null, CRYPTO_OP_ENCRYPT_DECRYPT);
                logStackTrace();
                this.init(opmode, key);
            };

            Cipher.init.overload('int', 'java.security.cert.Certificate').implementation = function(opmode, certificate) {
                console.log("\n📜 *** Cipher.init(Certificate) HOOKED ***");
                logKeyDetails(null, certificate, CRYPTO_OP_ENCRYPT_DECRYPT);
                logStackTrace();
                this.init(opmode, certificate);
            };

            // --- HOOKS: Signature (Sign/Verify) ---

            Signature.initSign.overload('java.security.PrivateKey').implementation = function(key) {
                console.log("\n✍️ *** Signature.initSign(PrivateKey) HOOKED ***");
                logKeyDetails(key, null, CRYPTO_OP_SIGN_VERIFY);
                logStackTrace();
                this.initSign(key);
            };

            Signature.initVerify.overload('java.security.PublicKey').implementation = function(key) {
                console.log("\n✅ *** Signature.initVerify(PublicKey) HOOKED ***");
                logKeyDetails(key, null, CRYPTO_OP_SIGN_VERIFY);
                logStackTrace();
                this.initVerify(key);
            };

            Signature.initVerify.overload('java.security.cert.Certificate').implementation = function(certificate) {
                console.log("\n📜 *** Signature.initVerify(Certificate) HOOKED ***");
                logKeyDetails(null, certificate, CRYPTO_OP_SIGN_VERIFY);
                logStackTrace();
                this.initVerify(certificate);
            };

            console.log("✅ Frida script loaded and cryptographic APIs hooked successfully!");

        } catch (e) {
            console.log("❌ Failed to load hooks (make sure target process is running): " + e);
        }
    });
} else {
    console.log("❌ Java is not available. Ensure Frida is attached to a JVM process.");
}

// Configuration parameter:
// Set to true to wait for the first call to getSettings() before enumerating WebViews.
// Set to false to enumerate immediately.
var delayEnumerationUntilGetSettings = true;

Java.perform(function() {
  var seenWebViews = {};
  var internalCall = false; // Flag to indicate internal calls

  // Function to print backtrace with a configurable number of lines (default: 5)
  function printBacktrace(maxLines = 8) {
    let Exception = Java.use("java.lang.Exception");
    let stackTrace = Exception.$new().getStackTrace().toString().split(",");

    console.log("\nBacktrace:");
    for (let i = 0; i < Math.min(maxLines, stackTrace.length); i++) {
        console.log(stackTrace[i]);
    }
    console.log("\n");
  }

  function enumerateWebViews() {
    Java.choose("android.webkit.WebView", {
      onMatch: function(instance) {
        var id = instance.toString();
        if (seenWebViews[id]) return;  // Skip if already seen
        seenWebViews[id] = true;
        Java.scheduleOnMainThread(function() {
          console.log(`\n[*] Found WebView instance: ${id}`);
          try {
            internalCall = true; // Set flag before calling getSettings
            var settings = instance.getSettings();
            internalCall = false; // Reset flag after calling getSettings
            console.log(`\t[+] JavaScriptEnabled: ${settings.getJavaScriptEnabled()}`);
            console.log(`\t[+] AllowFileAccess: ${settings.getAllowFileAccess()}`);
            console.log(`\t[+] AllowFileAccessFromFileURLs: ${settings.getAllowFileAccessFromFileURLs()}`);
            console.log(`\t[+] AllowUniversalAccessFromFileURLs: ${settings.getAllowUniversalAccessFromFileURLs()}`);
            console.log(`\t[+] AllowContentAccess: ${settings.getAllowContentAccess()}`);
            console.log(`\t[+] MixedContentMode: ${settings.getMixedContentMode()}`);
            console.log(`\t[+] SafeBrowsingEnabled: ${settings.getSafeBrowsingEnabled()}`);
          } catch (err) {
            console.log(`\t[-] Error reading settings: ${err}`);
          }
        });
      },
      onComplete: function() {
        console.log("\n[*] Finished enumerating WebView instances!");
      }
    });
  }

  var WebView = Java.use("android.webkit.WebView");

  if (delayEnumerationUntilGetSettings) {
    var enumerationTriggered = false;
    WebView.getSettings.implementation = function() {
      if (internalCall) {
        return this.getSettings(); // Return immediately if it's an internal call
      }
      var settings = this.getSettings();
      var id = this.toString();
      console.log(`\n[*] WebView.getSettings() called on instance: ${id}`);
      printBacktrace();
      if (!enumerationTriggered) {
        enumerationTriggered = true;
        Java.scheduleOnMainThread(function() {
          console.log("\n[*] Triggering enumeration after getSettings() call...");
          enumerateWebViews();
        });
      }
      return settings;
    };
  } else {
    enumerateWebViews();
  }
});

function enumerateDeleteAllDataMethod() {
